index_remove_tag.kernel_code:
fn index_remove_tag(index: &[IndexEntry], tag: Tag) -> Vec<IndexEntry> {
    let mut out: Vec<IndexEntry> = Vec::new();
    let mut i = 0;
    while i < index.len() {
        let e = index[i];
        if !tag_eq(e.tag, tag) {
            out.push(e);
        }
        i += 1;
    }
    out
}

replace_slot.kernel_code:
fn replace_slot(slots: &[Slot], id: u32, ns: Slot) -> Vec<Slot> {
    let mut out: Vec<Slot> = Vec::new();
    let mut i = 0;
    while i < slots.len() {
        let s = slots[i];
        if s.id == id {
            out.push(ns);
        } else {
            out.push(s);
        }
        i += 1;
    }
    out
}

delete_spool.kernel_code:
fn delete_spool(s: &Store, id: u32) -> Result<(Option<Store>, Reply), Error> {
    match lookup(&s.slots, id) {
        None => Ok((None, Reply::Deleted { found: false, void: NO_REGION, tag: NO_TAG })),
        Some(p) => {
            let slots = remove_id(&s.slots, id);
            let index = index_remove_tag(&s.index, p.tag);
            let ns = Store { file_len: s.file_len, last_id: s.last_id, slots, index };
            Ok((Some(ns), Reply::Deleted { found: true, void: Region { off: p.offset, len: p.length }, tag: p.tag }))
        }
    }
}

edit_spool.kernel_code:
fn edit_spool(s: &Store, id: u32, tag: Tag, len: u32, same: bool, readable: bool) -> Result<(Option<Store>, Reply), Error> {
    match lookup(&s.slots, id) {
        None => Err(Error::NotFound),
        Some(p) => {
            let (off, plan, fl, nlen) = if same {
                (p.offset, NO_PLAN, s.file_len, p.length)
            } else {
                if !len_ok(len) {
                    return Err(Error::TooBig);
                }
                if !readable {
                    return Err(Error::Unreadable);
                }
                let (o, pl, f) = place(s.file_len, Some(p), len)?;
                (o, pl, f, len)
            };
            let slots = replace_slot(&s.slots, id, Slot { id, tag, offset: off, length: nlen });
            let index = if !tag_empty(p.tag) && tag_empty(tag) { index_remove_tag(&s.index, p.tag) } else { s.index.clone() };
            let ns = Store { file_len: fl, last_id: s.last_id, slots, index };
            Ok((Some(ns), Reply::Wrote { plan }))
        }
    }
}

tag_empty.kernel_code:
fn tag_empty(t: Tag) -> bool {
    if t.base == 0 { t.dash == 0 } else { false }
}

add_spool.kernel_code:
fn add_spool(s: &Store, tag: Tag, len: u32, readable: bool) -> Result<(Option<Store>, Reply), Error> {
    if !len_ok(len) {
        return Err(Error::TooBig);
    }
    if !readable {
        return Err(Error::Unreadable);
    }
    if s.last_id >= MAX_ID {
        return Err(Error::Full);
    }
    let id = s.last_id + 1;
    let prev = lookup(&s.slots, id);
    let had = match prev {
        Some(_) => true,
        None => false,
    };
    let (off, plan, fl) = place(s.file_len, prev, len)?;
    let slots1 = put_slot(&s.slots, had, Slot { id, tag, offset: off, length: len });
    if tag_empty(tag) {
        let ns = Store { file_len: fl, last_id: id, slots: slots1, index: s.index.clone() };
        return Ok((Some(ns), Reply::Added { id, plan, strike: Strike::None }));
    }
    // `get_spool_by_hex_tag`: the index entry, if its spool still exists.
    let holder = lookup_opt(&slots1, index_get(&s.index, tag));
    match holder {
        None => {
            let index = index_insert(&s.index, tag, id);
            let ns = Store { file_len: fl, last_id: id, slots: slots1, index };
            Ok((Some(ns), Reply::Added { id, plan, strike: Strike::None }))
        }
        Some(b) => {
            if b.length >= MAX_REC || b.tag.dash >= MAX_REC {
                // The struck row does not serialise: `update_spool` fails
                // before touching the index; the tag still moves.
                let index = index_insert(&s.index, tag, id);
                let ns = Store { file_len: fl, last_id: id, slots: slots1, index };
                return Ok((Some(ns), Reply::Added { id, plan, strike: Strike::Failed { id: b.id } }));
            }
            let btag = Tag { base: b.tag.base, dash: b.tag.dash + 1 };
            let blen = b.length + 1;
            let (boff, bplan, fl2) = place(fl, Some(b), blen)?;
            let slots2 = replace_slot(&slots1, b.id, Slot { id: b.id, tag: btag, offset: boff, length: blen });
            let index1 = index_remove_id(&s.index, b.id);
            let index = index_insert(&index1, tag, id);
            let ns = Store { file_len: fl2, last_id: id, slots: slots2, index };
            Ok((Some(ns), Reply::Added { id, plan, strike: Strike::Done { id: b.id, tag: btag, plan: bplan } }))
        }
    }
}

