append_slot.kernel_code:
fn append_slot(slots: &[Slot], slot: Slot) -> Vec<Slot> {
    let mut out: Vec<Slot> = Vec::new();
    let mut i = 0;
    while i < slots.len() {
        out.push(slots[i]);
        i += 1;
    }
    out.push(slot);
    out
}

place.kernel_code:
fn place(file_len: u32, prev: Option<Slot>, len: u32) -> Result<(u32, Plan, u32), Error> {
    match prev {
        None => {
            if file_len > MAX_FILE - len {
                return Err(Error::Full);
            }
            let plan = Plan { void: NO_REGION, data: Region { off: file_len, len } };
            Ok((file_len, plan, file_len + len))
        }
        Some(p) => {
            if len <= p.length {
                // Fits: the whole old slot is rewritten (row, `-` padding,
                // `\n`); the record's tracked length becomes `len`.
                let plan = Plan { void: NO_REGION, data: Region { off: p.offset, len: p.length } };
                Ok((p.offset, plan, file_len))
            } else {
                if file_len > MAX_FILE - len {
                    return Err(Error::Full);
                }
                let plan = Plan { void: Region { off: p.offset, len: p.length }, data: Region { off: file_len, len } };
                Ok((file_len, plan, file_len + len))
            }
        }
    }
}

lookup.kernel_code:
fn lookup(slots: &[Slot], id: u32) -> Option<Slot> {
    let mut i = 0;
    while i < slots.len() {
        if slots[i].id == id {
            return Some(slots[i]);
        }
        i += 1;
    }
    None
}

index_remove_id.kernel_code:
fn index_remove_id(index: &[IndexEntry], id: u32) -> Vec<IndexEntry> {
    let mut out: Vec<IndexEntry> = Vec::new();
    let mut i = 0;
    while i < index.len() {
        let e = index[i];
        if e.id != id {
            out.push(e);
        }
        i += 1;
    }
    out
}

remove_id.kernel_code:
fn remove_id(slots: &[Slot], id: u32) -> Vec<Slot> {
    let mut out: Vec<Slot> = Vec::new();
    let mut i = 0;
    while i < slots.len() {
        let s = slots[i];
        if s.id != id {
            out.push(s);
        }
        i += 1;
    }
    out
}

IndexEntry.kernel_code:
pub struct IndexEntry {
    pub tag: Tag,
    pub id: u32,
}

index_insert.kernel_code:
fn index_insert(index: &[IndexEntry], tag: Tag, id: u32) -> Vec<IndexEntry> {
    let mut out: Vec<IndexEntry> = Vec::new();
    let mut found = false;
    let mut i = 0;
    while i < index.len() {
        let e = index[i];
        if tag_eq(e.tag, tag) {
            out.push(IndexEntry { tag, id });
            found = true;
        } else {
            out.push(e);
        }
        i += 1;
    }
    if !found {
        out.push(IndexEntry { tag, id });
    }
    out
}

read_only.kernel_code:
pub fn read_only(cmd: &Command) -> bool {
    match cmd {
        Command::Query => true,
        _ => false,
    }
}

Reply.kernel_code:
pub enum Reply {
    Added { id: u32, plan: Plan, strike: Strike },
    Wrote { plan: Plan },
    /// `found`: there was such a spool, and `void` is its old slot.
    Deleted { found: bool, void: Region, tag: Tag },
    Listing,
}

index_get.kernel_code:
fn index_get(index: &[IndexEntry], tag: Tag) -> Option<u32> {
    let mut i = 0;
    while i < index.len() {
        if tag_eq(index[i].tag, tag) {
            return Some(index[i].id);
        }
        i += 1;
    }
    None
}

Error.kernel_code:
pub enum Error {
    /// The row does not serialise in `MAX_REC` bytes.
    TooBig,
    /// The file would grow past `MAX_FILE`, or ids are exhausted.
    Full,
    /// No such spool id (edit).
    NotFound,
    /// The request did not decrypt.
    Forbidden,
    /// The row would not load back at boot (a field over the reader's
    /// 256-byte buffer, a newline in a field). Upstream writes it, and the
    /// whole inventory is unavailable after the next reset.
    Unreadable,
}

Command.kernel_code:
pub enum Command {
    /// Add a spool whose row is `len` bytes, with NFC tag `tag`;
    /// `readable`: the row reads back as the same record through the boot
    /// loader (`CsvDb::start`: one line, a 256-byte field buffer).
    AddSpool { tag: Tag, len: u32, readable: bool },
    /// Rewrite spool `id`: its row is now `len` bytes and its tag `tag`;
    /// `same`: the record is unchanged (`CsvDb::insert` writes nothing).
    EditSpool { id: u32, tag: Tag, len: u32, same: bool, readable: bool },
    /// Delete spool `id` (a missing id is not an error upstream).
    DeleteSpool { id: u32 },
    /// Read the inventory.
    Query,
}
